import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

leak = verify('kv_leak', '''
    use core.storage;
    fn main() -> i32 {
        let store = storage.kv_open("session.kv")
        discard storage.kv_put(store, "session:key", "value")
        return 0
    }
''', 1)
assert any('linear value `store` was not consumed/freed' in message for message in messages(leak)), leak

wrapper = verify('kv_wrapper', '''
    use core.storage;
    fn close_store(store: KvStoreHandle) -> i32 {
        return storage.kv_close(store)
    }
    fn main() -> i32 {
        let store = storage.kv_open("session.kv")
        discard storage.kv_put(store, "session:key", "value")
        discard close_store(store)
        return 0
    }
''', 0)
assert wrapper['errors'] == 0, wrapper

reuse = verify('kv_reuse', '''
    use core.storage;
    fn close_store(store: KvStoreHandle) -> i32 {
        return storage.kv_close(store)
    }
    fn main() -> i32 {
        let store = storage.kv_open("session.kv")
        discard storage.kv_put(store, "session:key", "value")
        discard close_store(store)
        discard storage.kv_close(store)
        return 0
    }
''', 1)
assert any('uses moved value `store` after move/consume' in message for message in messages(reuse)), reuse

returned = verify('kv_return', '''
    use core.storage;
    fn open_store() -> KvStoreHandle {
        return storage.kv_open("session.kv")
    }
    fn main() -> i32 {
        let store = open_store()
        discard storage.kv_put(store, "session:key", "value")
        discard storage.kv_close(store)
        return 0
    }
''', 0)
assert returned['errors'] == 0, returned
assert not any('potential resource escape' in message for message in messages(returned)), returned

artifact_root = write_project('kv_artifacts', '''
    use core.storage;
    fn main() -> i32 {
        let store = storage.kv_open("session.kv")
        discard storage.kv_put(store, "session:key", "value")
        discard storage.kv_close(store)
        return 0
    }
''')
artifact_proc = subprocess.run([str(fz), 'verify', str(artifact_root), '--json'], cwd=str(repo), capture_output=True, text=True)
artifact_payload = json.loads(artifact_proc.stdout.strip())
assert artifact_proc.returncode == 0 and artifact_payload['errors'] == 0, (artifact_proc.returncode, artifact_payload, artifact_proc.stderr)
memory_report = json.loads((artifact_root / '.fz' / 'memory-report.json').read_text())
contracts = json.loads((artifact_root / '.fz' / 'native-runtime-contracts.json').read_text())
assert 'KvStoreHandle' in json.dumps(memory_report), memory_report
contracts_text = json.dumps(contracts)
assert 'storage.kv_open' in contracts_text and 'owned_kv_store' in contracts_text, contracts
assert 'storage.kv_close' in contracts_text and 'consume_arg0' in contracts_text, contracts

print('compiler-memory-kv-handles-ok')

